"""Fixed, reviewable 80-question corpus. Expected plans are authored, never generated by the parser."""


def answer(question, metric="total_revenue", dept=None, start="2025-01", end="2025-12", **extra):
    expected = {"metrics": [metric], "departments": [dept] if dept else [], "department_types": [],
                "start_month": start, "end_month": end, "group_by": [], "comparison": "none", "unit": "yuan"}
    expected.update(extra)
    return {"question": question, "category": "answerable", "status": "success", "expected_plan": expected}


